            print(f"    Attributes: {attrs}")
            for attr in attrs:
                try:
                    val = getattr(c, attr)
                    if not callable(val):
                        print(f"      {attr}: {val}")
                except:
                    pass

FreeCAD.closeDocument(doc.Name)
